'use strict';
// Local simulation only. Real balances and schedules require an authoritative server.
const Economy=(()=>{
const MIN=60000,HOUR=3600000,ZONE=8*HOUR;
const JOBS=[['便利商店理貨','整理貨架、點貨，讓鄰居買得安心。','tiger-police'],['廟口環境巡檢','沿著老街巡視，協助店家整理環境。','bear-warden'],['工地物料整理','穿好防護裝備，協助工班搬運材料。','boar-builder'],['重機現場支援','協助機具調度與現場施工紀錄。','ox-demolition'],['港口設備維護','在海風中，完成今日的設備保養。','leopard-welder'],['山城救護站助理','補充救護用品，支援救護站日常。','rabbit-medic'],['社區健康站接待','協助居民報到與整理衛教資料。','deer-nurse'],['醫療物資盤點','確認物資清單，讓醫護安心值勤。','cat-surgeon'],['農田無人機巡查','檢查田區影像，紀錄作物狀態。','otter-drone'],['智慧街區測試','測試智慧設備，整理訊號紀錄。','fox-engineer'],['晶圓資料整理','核對產線資料，支援工程師作業。','owl-chip'],['城市設施巡查','檢查公共設施，記錄待維護項目。','rhino-commander']];
const ITEMS=[['舊螺帽',3,20,'⚙'],['紙袋',4,16,'▧'],['橡皮筋',5,12,'⌁'],['便條紙',6,10,'▤'],['木夾',8,8,'▥'],['原子筆',10,7,'✎'],['明信片',12,6,'▧'],['傳輸線',15,5,'⌁'],['小茶杯',20,4,'♨'],['復古徽章',25,3,'✦'],['布製杯墊',30,2.5,'◈'],['工具套',40,2,'⚒'],['紀念晶片',55,1.5,'▣'],['琉璃珠',75,1,'●'],['職人工藝杯',100,.7,'♨'],['港都銅牌',140,.5,'◉'],['木雕擺件',190,.35,'♜'],['限定音樂盒',260,.25,'♫'],['金箔書籤',360,.15,'✧'],['典藏懷錶',500,.1,'◷']].map(([name,sell,weight,icon],i)=>({id:'item'+i,name,sell,weight,icon}));
const GOODS=[{id:'tea',name:'冰涼烏龍茶',icon:'🍵',price:200,energy:10,limit:3,currency:'cash',desc:'每日限購 3 瓶'},{id:'rice',name:'台式飯糰',icon:'🍙',price:500,energy:30,limit:2,currency:'cash',desc:'每日限購 2 份'},{id:'bento',name:'鐵路便當',icon:'🍱',price:800,energy:50,limit:1,currency:'cash',desc:'每日限購 1 份'},{id:'tonic',name:'黃金元氣飲',icon:'🥤',price:30,energy:70,limit:2,currency:'premium',desc:'黃金限定 · 每日 2 瓶'},{id:'feast',name:'職人豪華定食',icon:'🍣',price:50,energy:100,limit:1,currency:'premium',desc:'黃金限定 · 每日 1 份'}];
const PRIZES=[{id:'a',name:'A賞・寶島虎虎公仔',icon:'🐯',sell:1000,weight:2},{id:'b',name:'B賞・海島風景擺飾',icon:'🏝',sell:300,weight:8},{id:'c',name:'C賞・職人隨行杯',icon:'☕',sell:140,weight:30},{id:'d',name:'D賞・城市小吊飾',icon:'🎐',sell:90,weight:60},{id:'ga',name:'黃金A賞・典藏海島模型',icon:'🏯',sell:0,weight:5,gold:true,value:250},{id:'gb',name:'黃金B賞・限定虎虎雕像',icon:'🐯',sell:0,weight:15,gold:true,value:100},{id:'gc',name:'黃金C賞・光彩城市徽章',icon:'🎖',sell:0,weight:30,gold:true,value:50},{id:'gd',name:'黃金D賞・精裝職人收藏',icon:'🎁',sell:0,weight:50,gold:true,value:35}];
const STOCKS=[{id:'9001',name:'島嶼晶圓',sector:'半導體',base:12850},{id:'9002',name:'港灣物流',sector:'航運物流',base:4280},{id:'9003',name:'山海食研',sector:'食品生技',base:7630},{id:'9004',name:'寶島能源',sector:'綠色能源',base:9550},{id:'9005',name:'旺來文創',sector:'文化創意',base:2860}];
STOCKS.push(...[['9006','客庄精工','工具機',6520],['9007','蘭陽旅宿','觀光',3850],['9008','南國果業','農業',2130],['9009','海島電信','通訊',8640],['9010','山城製藥','生技',11020],['9011','曙光運輸','交通',5160]].map(([id,name,sector,base])=>({id,name,sector,base})));
const BINGO_PAY={1:{1:2},2:{1:1,2:3},3:{2:2,3:20},4:{2:1,3:4,4:40},5:{3:2,4:20,5:300},6:{3:1,4:8,5:40,6:1000},7:{3:1,4:2,5:12,6:120,7:3200},8:{0:1,4:1,5:8,6:40,7:800,8:20000},9:{0:1,4:1,5:4,6:20,7:120,8:4000,9:40000},10:{0:1,5:1,6:10,7:100,8:1000,9:10000,10:200000}};
function seeded(str){let h=2166136261;for(const c of String(str)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return()=>{h+=0x6D2B79F5;let t=h;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;};}
const int=(rng,n)=>Math.floor(rng()*n);
function sample(max,count,rng=Math.random){const a=Array.from({length:max},(_,i)=>i+1);for(let i=a.length-1;i>0;i--){const j=int(rng,i+1);[a[i],a[j]]=[a[j],a[i]];}return a.slice(0,count);}
function offers(rng=Math.random,level=1){return sample(JOBS.length,level+2,rng).map((n,i)=>{const stars=1+int(rng,5);return {uid:`${Date.now()}-${i}-${int(rng,100000000)}`,job:n-1,stars,rate:Math.round([0,100,150,200,250,300][stars]*(1+(level-1)*.075)+1e-8),energy:[0,8,12,16,20,24][stars]};});}
const LEVEL_TAX=[0,1000,3000,7000,15000,30000,60000,120000,240000,500000];
const cents=n=>Math.round(n*100)/100;
function city(st,name=st.city){const total=st.cityTaxes?.[name]||0;let level=1;while(level<10&&total>=LEVEL_TAX[level])level++;return {level,total,next:LEVEL_TAX[level]??null,start:LEVEL_TAX[level-1],jobs:level+2,bonus:(level-1)*7.5,stocks:Math.min(STOCKS.length,level+1)};}
function tax(st,amount,label,now=Date.now()){const value=cents(amount*.1);st.tax=cents(st.tax+value);const name=st.city||'未選城市';st.cityTaxes[name]=cents((st.cityTaxes[name]||0)+value);return value;}
function day(now=Date.now()){return Math.floor((now+ZONE)/(24*HOUR));}
function daily(st,now=Date.now()){if(st.daily.day!==day(now))st.daily={day:day(now),refresh:0,goods:{}};}
function upgrade(st,now=Date.now()){if(st.version===4){for(const x of STOCKS){if(!Number.isFinite(st.market.prices[x.id]))st.market.prices[x.id]=x.base;st.market.history[x.id]??=[x.base];}return st;}if(st.job){st.cash+=st.job.rate*st.job.minutes;st.job=null;}for(const t of st.tickets||[])if(t.status==='pending')st.cash+=t.stake;st.version=4;for(const x of STOCKS){if(!Number.isFinite(st.market.prices[x.id]))st.market.prices[x.id]=x.base;st.market.history[x.id]??=[x.base];}st.playerId='島民'+String(st.seed).slice(-6).padStart(6,'0');st.tax=0;st.cityTaxes={};st.jobs=[];st.jobResults=[];st.offers=offers(Math.random,1);st.jobResult=null;st.inventory={};st.collectibles={};st.tickets=[];st.epoch=now;st.daily={day:day(now),refresh:0,goods:{}};st.pools={slots:100000,lotto:10000000};st.broadcasts=[];st.lastSlots=null;st.shorts={};st.lottoResults={};st.ledger=[];log(st,'城市成長版啟用：舊工作結薪、待開獎退回，新稅務與期別從零開始',0,now);return st;}
function period(st,type,now=Date.now()){const size=type==='bingo'?5*MIN:12*HOUR,id=Math.max(1,Math.floor((now-st.epoch)/size)+1);return {id,end:st.epoch+id*size,period:size};}
function refresh(st,now=Date.now(),rng=Math.random){daily(st,now);const cost=st.daily.refresh*50;if(st.premium<cost)throw Error('黃金不足');st.premium-=cost;st.daily.refresh++;st.offers=offers(rng,city(st).level);log(st,cost?'刷新就業所，使用 '+cost+' 黃金':'每日免費刷新就業所',0,now);}
function weighted(list,rng){let n=rng()*list.reduce((a,x)=>a+x.weight,0);for(const x of list){n-=x.weight;if(n<0)return x;}return list.at(-1);}
function announce(st,text,now){st.broadcasts.unshift({text,at:now});st.broadcasts=st.broadcasts.slice(0,20);}
function initial(old={},now=Date.now(),rng=Math.random){return {version:3,city:old.city||null,cash:Number.isFinite(old.gold)?Math.max(0,old.gold):3600,energy:Math.min(100,Math.max(0,old.energy??100)),energyAt:old.energyAt||now,exp:old.xp||0,tax:old.rep||0,premium:old.premium||0,donated:old.donated||0,facility:old.facility||[1,1,1],seed:String(int(rng,2147483647)),offers:offers(rng),job:null,jobResult:null,inventory:{},food:{tea:1},collectibles:{},tickets:[],ledger:[],holdings:{},market:{hour:Math.floor(now/HOUR),prices:Object.fromEntries(STOCKS.map(s=>[s.id,s.base])),history:Object.fromEntries(STOCKS.map(s=>[s.id,[s.base]]))},lastSlots:null};}
function log(st,text,delta=0,now=Date.now()){st.ledger.unshift({text,delta,at:now});st.ledger=st.ledger.slice(0,50);}
function energy(st,now){if(st.energy>=100){st.energy=100;st.energyAt=now;return;}const n=Math.floor(Math.max(0,now-st.energyAt)/(5*MIN));if(n>0){st.energy=Math.min(100,st.energy+n);st.energyAt+=n*5*MIN;if(st.energy===100)st.energyAt=now;}}
function round(type,now=Date.now()){const period=type==='bingo'?5*MIN:12*HOUR;const id=Math.floor((now+ZONE)/period);return {id,end:(id+1)*period-ZONE,period};}
function draw(type,id,seed){const a=sample(type==='bingo'?80:49,type==='bingo'?20:7,seeded(seed+':'+type+':'+id));return type==='bingo'?{numbers:a,super:a[19]}:{numbers:a.slice(0,6),special:a[6]};}
function payout(ticket,result){if(ticket.type==='lotto'){const hits=ticket.numbers.filter(n=>result.numbers.includes(n)).length,special=ticket.numbers.includes(result.special);let prize=0,tier='未中獎';if(hits===6){prize=10000000;tier='頭獎';}else if(hits===5&&special){prize=1000000;tier='貳獎';}else if(hits===5){prize=100000;tier='參獎';}else if(hits===4&&special){prize=10000;tier='肆獎';}else if(hits===4){prize=2000;tier='伍獎';}else if(hits===3&&special){prize=1000;tier='陸獎';}else if(hits===2&&special){prize=400;tier='柒獎';}else if(hits===3){prize=400;tier='普獎';}return {prize,tier,hits};}
let multiplier=0,hits=0;const mode=ticket.mode;if(mode==='basic'){hits=ticket.numbers.filter(n=>result.numbers.includes(n)).length;multiplier=BINGO_PAY[ticket.numbers.length]?.[hits]||0;}else if(mode==='super'){hits=ticket.numbers[0]===result.super?1:0;multiplier=hits?48:0;}else{const predicate=mode==='small'?n=>n<=40:mode==='big'?n=>n>=41:mode==='odd'?n=>n%2===1:n=>n%2===0;hits=result.numbers.filter(predicate).length;multiplier=hits>=13?6:0;}return {prize:ticket.stake*multiplier,hits,tier:multiplier?`${multiplier} 倍`:'未中獎'};}
function marketTick(st,now){const hour=Math.floor(now/HOUR);if(hour<=st.market.hour)return;for(let h=st.market.hour+1;h<=hour;h++){for(const stock of STOCKS){const rng=seeded(st.seed+':market:'+stock.id+':'+h),change=(int(rng,2001)-1000)/10000;const price=Math.max(100,Math.min(10000000,Math.round(st.market.prices[stock.id]*(1+change))));st.market.prices[stock.id]=price;st.market.history[stock.id].push(price);st.market.history[stock.id]=st.market.history[stock.id].slice(-24);const sh=st.shorts?.[stock.id];if(sh?.qty&&(sh.margin+sh.proceeds)/(sh.qty*price/100)<1.3)closeShort(st,stock.id,sh.qty,h*HOUR,true);}}st.market.hour=hour;}
function settle(st,now=Date.now()){upgrade(st,now);energy(st,now);daily(st,now);marketTick(st,now);
for(const j of st.jobs.filter(j=>j.end<=now)){const rng=seeded(st.seed+':job:'+j.uid),drops=[];for(let i=0;i<j.stars;i++){const item=weighted(ITEMS,rng);st.inventory[item.id]=(st.inventory[item.id]||0)+1;drops.push(item.id);}const withheld=tax(st,j.rate,'工作勞健保稅',now),pay=cents(j.rate-withheld);st.cash=cents(st.cash+pay);st.exp+=j.stars*10;st.jobResults.unshift({...j,pay,drops});st.jobResults=st.jobResults.slice(0,12);log(st,'工作完成 '+JOBS[j.job][0]+'（勞健保稅 '+withheld+'）',pay,now);}st.jobs=st.jobs.filter(j=>j.end>now);
const bgroups={};for(const t of st.tickets.filter(t=>t.type==='bingo'&&t.status==='pending'&&t.end<=now)){t.result=draw('bingo',t.round,st.seed);t.award=payout(t,t.result);const family=['small','big'].includes(t.mode)?'size':['odd','even'].includes(t.mode)?'parity':t.mode;const key=t.round+':'+family+(t.mode==='basic'?t.numbers.length:'');(bgroups[key]??=[]).push(t);}for(const group of Object.values(bgroups)){const first=group[0],limit=first.mode==='basic'?(first.numbers.length===10?100000000:10000000):20000000,total=group.reduce((a,t)=>a+t.award.prize,0);for(const t of group){if(total>limit){t.award.prize=Math.floor(t.award.prize*limit/total);t.award.tier+='（單期上限按比例）';}t.status='settled';st.cash=cents(st.cash+t.award.prize);log(st,'賓狗第 '+t.round+' 期 '+t.award.tier,t.award.prize,now);}}
const rounds=[...new Set(st.tickets.filter(t=>t.type==='lotto'&&t.status==='pending'&&t.end<=now).map(t=>t.round))].sort((a,b)=>a-b);
for(const id of rounds){const tickets=st.tickets.filter(t=>t.type==='lotto'&&t.round===id&&t.status==='pending'),result=draw('lotto',id,st.seed);st.pools.lotto=cents(st.pools.lotto+tickets.length*45);const pool=st.pools.lotto;for(const t of tickets){t.result=result;t.award=payout(t,result);}const low=tickets.filter(t=>['伍獎','陸獎','柒獎','普獎'].includes(t.award.tier)),lowTotal=low.reduce((a,t)=>a+t.award.prize,0);const lowBudget=Math.min(pool,lowTotal);for(const t of low)t.award.prize=Math.floor(t.award.prize*(lowTotal?lowBudget/lowTotal:0));let remaining=pool-low.reduce((a,t)=>a+t.award.prize,0);const base=remaining;for(const [tier,ratio] of [['貳獎',.065],['參獎',.07],['肆獎',.045]]){const winners=tickets.filter(t=>t.award.tier===tier);const each=winners.length?Math.floor(base*ratio/winners.length):0;for(const t of winners)t.award.prize=each;remaining-=each*winners.length;}const heads=tickets.filter(t=>t.award.tier==='頭獎');if(heads.length){const each=Math.floor(remaining/heads.length);for(const t of heads)t.award.prize=each;remaining-=each*heads.length;announce(st,st.playerId+' 中了第 '+id+' 期大樂透頭獎！',now);}for(const t of tickets){t.status='settled';st.cash=cents(st.cash+t.award.prize);log(st,'大樂透第 '+id+' 期 '+t.award.tier,t.award.prize,now);}st.lottoResults[id]={pool,paid:pool-remaining};st.pools.lotto=Math.max(10000000,remaining);}
for(const [id,h] of Object.entries(st.shorts)){if(h.qty&&(h.proceeds+h.margin)/(h.qty*st.market.prices[id]/100)<1.3)closeShort(st,id,h.qty,now,true);}
st.tickets=st.tickets.filter(t=>t.status==='pending').concat(st.tickets.filter(t=>t.status==='settled').slice(-100));return st;}
function accept(st,uid,minutes=60,now=Date.now()){settle(st,now);if(!st.city)throw Error('請先在台灣地圖加入縣市');const o=st.offers.find(x=>x.uid===uid);if(!o||minutes!==60)throw Error('每份工作為 60 分鐘');if(st.energy<o.energy)throw Error('電量不足');st.energy-=o.energy;const job={...o,minutes:60,start:now,end:now+HOUR};st.jobs.push(job);st.offers=st.offers.filter(x=>x.uid!==uid);log(st,'接下 '+JOBS[o.job][0],0,now);return job;}
function finishNotice(st){st.jobResults=[];}
function bet(st,type,mode,numbers,stake,now=Date.now()){settle(st,now);if(!st.city)throw Error('請先加入縣市');if(!['bingo','lotto'].includes(type))throw Error('遊戲不存在');const n=[...new Set(numbers)].sort((a,b)=>a-b);if(type==='lotto'){if(n.length!==6||n.some(x=>!Number.isInteger(x)||x<1||x>49))throw Error('請選 6 個號碼');stake=50;}else{if(!['basic','super','small','big','odd','even'].includes(mode)||![25,50,100].includes(stake))throw Error('玩法或金額無效');if(['basic','super'].includes(mode)&&(n.length<1||n.length>(mode==='super'?1:10)||n.some(x=>!Number.isInteger(x)||x<1||x>80)))throw Error('號碼無效');}if(st.cash<stake)throw Error('新台幣不足');if(st.tickets.filter(t=>t.status==='pending').length>=100)throw Error('等待開獎上限 100 注');const r=period(st,type,now);st.cash=cents(st.cash-stake);tax(st,stake,'娛樂稅',now);const t={id:now+'-'+st.tickets.length,type,mode,numbers:n,stake,round:r.id,end:r.end,status:'pending'};st.tickets.push(t);log(st,(type==='bingo'?'賓狗賓狗':'大樂透')+'第 '+r.id+' 期（內含娛樂稅 '+cents(stake*.1)+'）',-stake,now);return t;}
function slots(st,rng=Math.random,now=Date.now(),count=1){if(!st.city)throw Error('請先加入縣市');if(![1,10,50].includes(count)||st.cash<count*50)throw Error('新台幣不足或次數無效');const icons=['🥟','🐯','🐔','🍵','🧧','🍍','🏮','⭐'];let wins=0,total=0;for(let i=0;i<count;i++){st.cash=cents(st.cash-50);tax(st,50,'娛樂稅',now);const indexes=Array.from({length:3},()=>int(rng,32));const win=indexes[0]===0&&indexes[1]===1&&indexes[2]===2;const reels=indexes.map(x=>icons[x<3?x:3+(x-3)%5]);const prize=win?st.pools.slots:0;if(win){st.cash=cents(st.cash+prize);st.pools.slots=100000;wins++;total+=prize;announce(st,st.playerId+' 中了本次餃子老虎雞大獎 '+prize.toLocaleString()+' 新台幣！',now);}else st.pools.slots=cents(st.pools.slots+45);st.lastSlots={reels,prize,at:now};}st.lastSlots.total=total;st.lastSlots.wins=wins;st.lastSlots.count=count;log(st,'餃子老虎雞 '+count+' 次，'+wins+' 次大獎（娛樂稅 '+count*5+'）',total-count*50,now);return st.lastSlots;}
function buy(st,id,qty,now=Date.now()){daily(st,now);const g=GOODS.find(x=>x.id===id);if(!g||!Number.isInteger(qty)||qty<1)throw Error('數量無效');if((st.daily.goods[id]||0)+qty>g.limit)throw Error('已達每日限購數量');if(st[g.currency]<g.price*qty)throw Error('餘額不足');st[g.currency]-=g.price*qty;st.daily.goods[id]=(st.daily.goods[id]||0)+qty;st.food[id]=(st.food[id]||0)+qty;log(st,'購買 '+g.name+' ×'+qty,g.currency==='cash'?-g.price*qty:0,now);}
function use(st,id,now=Date.now()){energy(st,now);const g=GOODS.find(x=>x.id===id);if(!g||!st.food[id])throw Error('背包沒有這項補給');if(st.energy===100)throw Error('電量已滿，補給保留在背包');if(st.energy+g.energy>100)throw Error('會超過電量上限，請使用較小份補給');st.food[id]--;st.energy+=g.energy;if(st.energy===100)st.energyAt=now;log(st,'使用 '+g.name+'，電量 +'+g.energy);}
function sell(st,id,kind='item'){const item=(kind==='prize'?PRIZES:ITEMS).find(x=>x.id===id),bag=kind==='prize'?st.collectibles:st.inventory;if(!item||!bag[id])throw Error('沒有此物品');if(item.gold)throw Error('黃金收藏不能換成新台幣，可保留展示');bag[id]--;st.cash=cents(st.cash+item.sell);log(st,'出售 '+item.name,item.sell);}
function ichiban(st,rng=Math.random,gold=false){const price=gold?50:150,currency=gold?'premium':'cash';if(st[currency]<price)throw Error('餘額不足');const p=weighted(PRIZES.filter(p=>!!p.gold===gold),rng);st[currency]-=price;st.collectibles[p.id]=(st.collectibles[p.id]||0)+1;if(gold)st.food.tonic=(st.food.tonic||0)+1;log(st,(gold?'黃金':'新台幣')+'一番賞 '+p.name,gold?0:-price);return p;}
function closeShort(st,id,qty,now=Date.now(),forced=false){const h=st.shorts[id];if(!h||h.qty<qty)throw Error('空單不足');const fraction=qty/h.qty,cost=st.market.prices[id]*qty/100,fee=cents(cost*.1),release=cents((h.margin+h.proceeds)*fraction-cost-fee);if(!forced&&st.cash+release<0)throw Error('可用資金不足回補，請增加資金');st.cash=cents(st.cash+release);h.margin=cents(h.margin*(1-fraction));h.proceeds=cents(h.proceeds*(1-fraction));h.qty-=qty;tax(st,cost,'股市交易稅',now);log(st,(forced?'維持率不足，自動回補 ':'回補 ')+id+' '+qty+' 股（交易稅 '+fee+'）',release,now);return {total:cost,price:st.market.prices[id]/100};}
function trade(st,id,side,qty,now=Date.now()){settle(st,now);if(!STOCKS.some(s=>s.id===id)||!['buy','sell','short','cover'].includes(side)||!Number.isInteger(qty)||qty<1||qty>100000)throw Error('交易資料無效');if(!st.city)throw Error('請先加入縣市');if(['buy','short'].includes(side)&&!STOCKS.slice(0,city(st).stocks).some(x=>x.id===id))throw Error('城市尚未解鎖此標的');const price=st.market.prices[id],total=cents(price*qty/100),fee=cents(total*.1),h=st.holdings[id]||{qty:0,costCents:0};if(side==='cover')return closeShort(st,id,qty,now);if(side==='buy'){if(h.qty+qty>100000)throw Error('發行上限 100,000 股');if(st.cash<total+fee)throw Error('新台幣不足（含 10% 交易稅）');st.cash=cents(st.cash-total-fee);h.qty+=qty;h.costCents+=Math.round((total+fee)*100);}else if(side==='sell'){if(h.qty<qty)throw Error('持股不足');h.costCents-=Math.round(h.costCents*qty/h.qty);h.qty-=qty;st.cash=cents(st.cash+total-fee);}else{const sh=st.shorts[id]||{qty:0,margin:0,proceeds:0};if(sh.qty+qty>10000)throw Error('本機可借券上限 10,000 股');const margin=cents(total*.9);if(st.cash<margin+fee)throw Error('需要 90% 保證金及 10% 交易稅');st.cash=cents(st.cash-margin-fee);sh.qty+=qty;sh.margin=cents(sh.margin+margin);sh.proceeds=cents(sh.proceeds+total);st.shorts[id]=sh;}st.holdings[id]=h;tax(st,total,'股市交易稅',now);log(st,({buy:'買入',sell:'賣出',short:'融券賣出'})[side]+' '+id+' ×'+qty+'（交易稅 '+fee+'）',side==='sell'?total-fee:-(side==='short'?total*.9+fee:total+fee),now);return {price:price/100,total};}
return {upgrade,city,tax,daily,day,period,refresh,LEVEL_TAX,weighted,closeShort,MIN,HOUR,JOBS,ITEMS,GOODS,PRIZES,STOCKS,BINGO_PAY,seeded,sample,offers,initial,energy,round,draw,payout,marketTick,settle,accept,finishNotice,bet,slots,buy,use,sell,ichiban,trade,log};})();


